function openCatalogRepresentative(x){const E=extraState();E.currentEntry=x.entry;switch(x.entry){case 'requirement':D.page='requirement';break;case 'metric':D.page='studio';D.studioTab='foundation';D.professional='metrics';break;case 'enterprise-materials':D.page='studio';D.studioTab='foundation';D.professional='materials';break;case 'decision':D.page='decision';break;case 'refiner':D.page='refiner';break;case 'simlab':D.page='simlab';break;case 'model-pack':D.page='model-pack';break;case 'ppt-report':D.page='chat';D.panel='files';D.files=true;D.notice='回原项目 060_reports 的报告操作，按准确 md 稿生成 PPTX；未自动生成。';break;case 'db-link':D.page='chat';D.panel='files';D.files=true;D.notice='回原项目资料与来源授权入口，未扩大查询权限。';break;case 'trade-area-mcp':case 'weather-mcp':D.page='chat';D.panel='files';D.files=true;D.notice='回原 Task 能力与项目资料入口，仍需原任务级显式启用；未发查询。';break;case 'target-forecast':case 'coupon-forecast':case 'roi-forecast':case 'deep-research':case 'data-analysis':E.selectedSkill=x.id;D.page='skill-detail';break;default:D.notice='原入口 '+x.entry+' 未在本代表页完整演示，未回落其他对象。';}render();return true;}
function extraChange(key,el){const E=extraState();switch(key){case 'goal-perspective':E.perspective=el.value;break;case 'studio-search':E.studioQuery=el.value;break;case 'coverage-report':E.coverageReport=el.value;E.coverageCell=null;break;case 'extra-enterprise':E.enterprise=el.value;break;case 'personal-search':E.personalQuery=el.value;break;case 'personal-drafts':E.personalDrafts=el.checked;break;case 'personal-archived':E.personalArchived=el.checked;break;case 'market-search':E.catalogQuery=el.value;break;case 'market-tag':E.catalogTag=el.value;break;case 'decision-project':E.decisionFilter=el.value;if(el.value!=='all')selectProject(el.value);break;case 'decision-evidence':E.decisionEvidence=el.value;break;default:return false;}return true;}
